use std::fs

fn is_int(tok: string) -> bool {
    let mut digits = 0
    let mut first = true
    for c in tok.chars() {
        if first && c == '-' {
            first = false
        } else if c.is_ascii_digit() {
            digits += 1
            first = false
        } else {
            return false
        }
    }
    digits > 0
}

fn eval(line: string) -> string {
    let mut stack: Vec<int> = []
    for tok in line.split_whitespace() {
        if tok == "+" || tok == "-" || tok == "*" || tok == "/" {
            let n = stack.len()
            if n < 2 {
                return "error: underflow"
            }
            let b = stack[n - 1]
            let a = stack[n - 2]
            if tok == "/" && b == 0 {
                return "error: divzero"
            }
            stack.truncate(n - 2)
            let r = if tok == "+" { a + b } else if tok == "-" { a - b } else if tok == "*" { a * b } else { a / b }
            stack.push(r)
        } else if is_int(tok) {
            stack.push(tok.parse::<int>().unwrap_or(0))
        } else {
            return "error: token"
        }
    }
    if stack.len() != 1 {
        return "error: leftover"
    }
    "${stack[0]}"
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim().len() == 0 {
            continue
        }
        println(eval(line))
    }
}

